function writer() {
  const m = new Map();
  return {
    put(x, y, z, [block, state] = [], { onlyAir = false } = {}) { m.set(`${x},${y},${z}`, { pos: [x, y, z], block, state, onlyAir }); },
    erase(x, y, z) { m.delete(`${x},${y},${z}`); },
    get: (x, y, z) => m.get(`${x},${y},${z}`),
    has: (x, y, z) => m.has(`${x},${y},${z}`),
    entries: () => m.values(),
